  static function sample(){return ['summary'=>"Your business is well known locally and your Google rating is strong, which is a great foundation. Most new customers, however, now compare two or three options on Google Maps before calling, and several smaller gaps make it easier for them to pick a competitor.\n\nThe good news: the biggest gaps are in your Google profile and in how easy it is to contact you from your website – both can be improved within weeks.",'headline'=>'Closing the review gap and making it one tap to call could add 10–15 enquiries a month.','strengths'=>['Excellent 4.9★ average rating','Secure, mobile-friendly website','Ranking in the top 3 for the main search','Clear contact details on the website'],'market'=>['search_term'=>'digital marketing agency in Pune','monthly_searches'=>1900,'insight'=>'Business owners in Pune usually shortlist agencies from Google Maps and then check reviews and past work on the website before calling. Proof of results and quick responses matter more than price at the shortlist stage.','stats'=>[['value'=>'87%','label'=>'of consumers used Google to evaluate local businesses','source'=>'BrightLocal, 2023'],['value'=>'76%','label'=>'of people who search on a phone for something nearby visit a business within a day','source'=>'Google/Ipsos, 2016'],['value'=>'3×','label'=>'more likely to be considered when a profile is complete','source'=>'Google Business Profile Help'],['value'=>'53%','label'=>'of mobile visits are abandoned if a page takes over 3 seconds to load','source'=>'Google, 2016']]],'journey'=>['monthly_searches'=>1900,'profile_views'=>650,'actions'=>95,'customers'=>9,'note'=>'Estimated from typical local-pack click shares for a #1–3 position and industry conversion rates.'],'industry_trends'=>[['title'=>'AI answers are changing search','detail'=>'Google now shows AI summaries for many local searches. Businesses with complete profiles, reviews and clear service pages are the ones these summaries mention.'],['title'=>'Reviews decide the shortlist','detail'=>'Most people only consider businesses with 4+ stars and recent reviews. Review volume and freshness now matter as much as the rating itself.'],['title'=>'WhatsApp is the new contact form','detail'=>'In India most first enquiries now arrive on WhatsApp. A visible WhatsApp button and quick replies convert more visitors into conversations.']],'competitors_insight'=>'You lead on rating, but the two competitors just below you are collecting reviews faster and have more photos, which helps them appear for more searches.','findings'=>[['area'=>'Google Maps','title'=>'Profile is missing photos and hours','found'=>'Only 3 photos and no opening hours on your Google profile.','why'=>'Profiles with photos and hours get more calls and appear in “open now” searches.','fix'=>'Add 15–20 recent photos and set regular and holiday hours.','impact'=>'High','effort'=>'Low'],['area'=>'Reviews','title'=>'Review growth has slowed','found'=>'120 reviews; competitors average 26 but are adding them faster.','why'=>'Fresh reviews are a strong ranking and trust signal.','fix'=>'Ask every happy client with a short WhatsApp link after each project.','impact'=>'High','effort'=>'Low'],['area'=>'Conversion','title'=>'No analytics on the website','found'=>'Google Analytics is not installed.','why'=>'You cannot see which pages or channels bring enquiries.','fix'=>'Install GA4 with call and form tracking.','impact'=>'Medium','effort'=>'Low'],['area'=>'Speed','title'=>'Homepage loads slowly on mobile','found'=>'The homepage HTML alone took 2.9 seconds.','why'=>'Visitors leave slow pages before they enquire.','fix'=>'Compress images and defer non-essential scripts.','impact'=>'Medium','effort'=>'Medium'],['area'=>'Content','title'=>'Few dedicated service pages','found'=>'Only one service page is linked from the homepage.','why'=>'Each service needs its own page to appear for its searches.','fix'=>'Create one page per core service with local examples.','impact'=>'Medium','effort'=>'Medium']],'opportunity'=>['customer_value'=>60000,'current_enquiries_month'=>12,'potential_enquiries_month'=>24,'conversion_rate'=>20,'assumptions'=>'Based on your current position, typical local-pack click shares and a conservative 20% enquiry-to-client rate.'],'outcomes'=>[['metric'=>'Calls from Google Maps','today'=>'~12 / month','target'=>'20–25 / month','timeframe'=>'6 months'],['metric'=>'Google reviews','today'=>'120','target'=>'170+','timeframe'=>'6 months'],['metric'=>'Website enquiries','today'=>'Not tracked','target'=>'Tracked, +30%','timeframe'=>'3 months']],'plan'=>[['phase'=>'Weeks 1–2','title'=>'Fix the basics','actions'=>['Complete Google profile','Install tracking','Click-to-call & WhatsApp'],'result'=>'Every enquiry is measurable'],['phase'=>'Weeks 3–4','title'=>'Build trust','actions'=>['Review request system','Add case studies'],'result'=>'Steady flow of new reviews'],['phase'=>'Weeks 5–8','title'=>'Grow visibility','actions'=>['Service pages','Local citations'],'result'=>'Appear for more searches'],['phase'=>'Weeks 9–12','title'=>'Optimise','actions'=>['Speed improvements','Monthly reporting'],'result'=>'More enquiries per visitor']],'quick_wins'=>[['title'=>'Add 10 new photos','how'=>'Office, team and recent work – takes 15 minutes.'],['title'=>'Reply to every review','how'=>'A short personal reply shows you care.'],['title'=>'Set holiday hours','how'=>'Avoid losing “open now” searches.'],['title'=>'Ask 5 clients for reviews','how'=>'Send your review link on WhatsApp today.'],['title'=>'Make your number tappable','how'=>'Use a tel: link in the header.']],'how_we_help'=>[['service'=>'Google Business Profile management','what'=>'Weekly posts, photos and review replies.','result'=>'More profile views and calls'],['service'=>'Local SEO','what'=>'Service pages and local citations for Pune.','result'=>'Visible for more searches'],['service'=>'Conversion & tracking','what'=>'Analytics, call tracking and faster pages.','result'=>'More enquiries from the same traffic']],'sources'=>[['title'=>'Local Consumer Review Survey','publisher'=>'BrightLocal','year'=>'2023','url'=>'https://www.brightlocal.com/research/local-consumer-review-survey/'],['title'=>'Understanding consumers’ local search behavior','publisher'=>'Google / Ipsos','year'=>'2016','url'=>'https://www.thinkwithgoogle.com/'],['title'=>'Find out how mobile page speed impacts consumers','publisher'=>'Google','year'=>'2016','url'=>'https://www.thinkwithgoogle.com/'],['title'=>'Tips to improve your local ranking on Google','publisher'=>'Google Business Profile Help','year'=>'2024','url'=>'https://support.google.com/business/answer/7091']],'closing'=>'Thank you for taking the time to read this. Even if you only act on the quick wins, you should see a difference within a few weeks – and we are always happy to answer questions.'];}
  static function pdf($html){
    $o=new Options();
    $o->set(['isRemoteEnabled'=>false,'isHtml5ParserEnabled'=>true,'chroot'=>[ROOT],'fontDir'=>STORAGE.'/fonts','fontCache'=>STORAGE.'/fonts','tempDir'=>STORAGE.'/tmp','defaultFont'=>'DejaVu Sans','dpi'=>96]);
    $d=new Dompdf($o);
    $d->setPaper('A4','landscape');
    $d->loadHtml($html,'UTF-8');
    $d->render();
    return $d->output();}}
